show("void categories", """SELECT void_cat_id, void_cat_name, count(*) n, round(sum(amount)) amt, round(avg((manager_id IS NULL OR manager_id=0)::INT),3) no_mgr, round(avg((manager_id=employee_id)::INT),3) self_appr FROM voids GROUP BY ALL ORDER BY n DESC""", 30)
show("void numeric", "SELECT count(*) FILTER (WHERE amount<=0) amt_le0, count(*) FILTER (WHERE quantity<=0) q_le0, max(amount) mx, approx_quantile(amount,[0.5,0.95,0.999]) q, count(DISTINCT employee_id) n_emp, count(DISTINCT manager_id) n_mgr FROM voids")
show("item discount names top", """SELECT discount_name, count(*) n, round(sum(amount)) amt, round(avg((manager_id IS NULL OR manager_id=0)::INT),3) no_mgr, round(avg((manager_id=employee_id)::INT),3) self_appr FROM item_discounts GROUP BY 1 ORDER BY amt DESC""", 25)
show("check discount names top", """SELECT discount_name, count(*) n, round(sum(amount)) amt, round(avg((manager_id IS NULL OR manager_id=0)::INT),3) no_mgr, round(avg((manager_id=employee_id)::INT),3) self_appr FROM check_discounts GROUP BY 1 ORDER BY amt DESC""", 25)
show("distinct discount names", "SELECT (SELECT count(DISTINCT discount_name) FROM item_discounts) item_names, (SELECT count(DISTINCT discount_name) FROM check_discounts) check_names, (SELECT count(*) FROM item_discounts WHERE amount<=0) idisc_le0, (SELECT count(*) FROM check_discounts WHERE amount<=0) cdisc_le0")
show("payment types", """SELECT pay_cat_name, count(*) n, round(sum(amount)) amt, round(sum(gratuity)) grat, bool_or(is_credit_card) cc, bool_or(is_gift_card) gc, bool_or(is_petty_cash) pc, bool_or(is_non_pos) nonpos, bool_or(is_cash_debit) cashdeb FROM payments GROUP BY 1 ORDER BY n DESC""", 40)
show("payment amount sanity", "SELECT count(*) FILTER (WHERE amount<0) neg, count(*) FILTER (WHERE amount=0) zero, max(amount) mx, approx_quantile(amount,[0.5,0.99,0.9999]) q FROM payments")
show("tax categories", "SELECT tax_cat_id, tax_cat_name, count(*) n, round(sum(amount)) amt, count(*) FILTER (WHERE amount<0) neg FROM taxes GROUP BY ALL ORDER BY n DESC", 20)
